using System;using Ashfall.Core;using Ashfall.Modules.HealthStates;using Ashfall.Integration.Playable.HandsWeapons;
partial class Cases:IAuthorityGate,IHealthWorld,IInteractionQuery
{
 static int checks;long sequence;public double Now{get{return 1;}}public bool InMatch{get{return true;}}public bool TeamChangesAllowed{get{return false;}}public bool TryGetPose(string id,out RescuePose pose){pose=new RescuePose();return false;}public RuleResult Validate(CommandContext c){return c.IsAuthority?RuleResult.Accept():RuleResult.Reject("authority");}public bool HasLineOfSight(string a,string b,Float3 c,Float3 d,float range){return true;}CommandContext C(){return new CommandContext("knife-health","player","case/"+(++sequence),sequence,0,true);}
 static void Check(bool yes,string why){checks++;if(!yes)throw new Exception(why);}
 static R23ShotPose Unit{get{return new R23ShotPose(new Float3(),new Float3(1,0,0),new Float3(0,1,0),new Float3(0,0,1));}}
 static R23ShotPose Shift(float x){return new R23ShotPose(new Float3(x,0,0),Unit.Right,Unit.Up,Unit.Forward);}
 static R24KnifeSweep Frame(R24KnifeRuntime knife,float x,string[] overlaps=null,bool usable=true,R23ShotPose? actor=null){var a=actor??Unit;return knife.BeginFrame(.1f,usable,a,a.Point(new Float3(x,0,0)),a.Point(new Float3(x,.221f,0)),a.Point(new Float3(x,-.08f,0)),overlaps??new string[0]);}
 static R24KnifeEntry[] Steps(R24KnifeRuntime knife,R24KnifeSweep sweep,bool touching){var result=new System.Collections.Generic.List<R24KnifeEntry>();for(int i=0;i<sweep.Steps;i++){var ids=touching?new[]{"target"}:new string[0];result.AddRange(knife.SampleStep(sweep,i,ids,ids,ids));}return result.ToArray();}
 void Run(){RoundIntegration();var k=new R24KnifeRuntime("knife/1");Check(Frame(k,0)==null,"initial empty geometry seed");var s=Frame(k,.2f);Check(s!=null&&s.Steps==8&&Math.Abs(s.BladeSpeed-2)<.0001f&&Math.Abs(s.HandSpeed-2)<.0001f,"source .026 spatial subdivisions and actor-local motion");Check(k.WhooshRequested&&k.WhooshEvents==1&&Math.Abs(k.WhooshPitch-.94f)<.0001f,"source whoosh requires movement speed and travel");var entries=Steps(k,s,true);Check(entries.Length==1&&entries[0].TargetId=="target"&&entries[0].Damage==35,"real bound native contact entry once through continuous stroke");var health=new HealthService("knife-health",0,0,false,this,this,this,60,5,0);health.Register(C(),"target",-1,false);Func<string,float,bool> hit=delegate(string id,float amount){var before=health.Read(id);return health.ApplyLoss(C(),id,before.Revision,Math.Min(amount,before.Health),0,false).Accepted;};Check(k.ApplyContact(entries[0],hit)&&health.Read("target").Shield==100&&health.Read("target").Health==65,"actual HealthService receives source flat35");Check(!k.ApplyContact(entries[0],hit)&&health.Read("target").Shield==100&&health.Read("target").Health==65,"same native entry cannot replay damage");s=Frame(k,.2f,new[]{"target"});Check(Steps(k,s,true).Length==0,"resting inside target never becomes repeated strikes");s=Frame(k,.4f);Check(Steps(k,s,false).Length==0,"real spatial exit rearms without damage");s=Frame(k,.2f);entries=Steps(k,s,true);Check(entries.Length==1&&entries[0].Sequence==2&&k.ApplyContact(entries[0],hit)&&health.Read("target").Shield==100&&health.Read("target").Health==30,"physical reentry new native identity no wall-clock damage cooldown");Check(k.AcceptedContacts==2&&k.Snapshot.Loaded==0&&k.Snapshot.Phase==Ashfall.Modules.WeaponHandling.ReloadPhase.Ready,"melee native observations contain no fake magazine");
  var inside=new R24KnifeRuntime("inside");Check(Frame(inside,0,new[]{"target"})==null,"equip inside real overlap seeds without damage");Check(Steps(inside,Frame(inside,.05f,new[]{"target"}),true).Length==0,"overlap persists while moving below full travel");inside.SuspendControls();Check(Frame(inside,.1f,new[]{"target"})==null,"holster/focus seeds current overlap on resume");Check(Steps(inside,Frame(inside,.2f,new[]{"target"}),true).Length==0,"resume inside overlap cannot synthesize entry");var other=new R24KnifeRuntime("knife/2");Frame(other,0);Check(Steps(other,Frame(other,.2f),true).Length==1&&other.AcceptedContacts==1&&k.AcceptedContacts==2,"independent native contact owner per copy");Check(!other.ApplyContact(entries[0],hit),"foreign weapon entry refused");Check(Frame(other,2)==null,"source >1m tracking jump suspended");Check(Frame(other,2.1f,new[]{"target"})==null,"recovered tracking jump seeds inside target");Frame(other,2.1f,null,false);Check(Frame(other,2.2f,new[]{"target"})==null,"climb/pause/unusable never creates entry");
  var movingRoot=new R24KnifeRuntime("locomotion");Frame(movingRoot,0);s=Frame(movingRoot,0,null,true,Shift(20));Check(s!=null&&s.Travel==0&&s.BladeSpeed==0&&Steps(movingRoot,s,true).Length==0,"20m root teleport carries actor-local blade without swing damage");var slow=new R24KnifeRuntime("slow");Frame(slow,0);s=Frame(slow,.01f);Check(!slow.WhooshRequested&&Steps(slow,s,true).Length==0,"blade speed below .20 has no contact damage or whoosh");
  s=Frame(k,.4f);Check(k.SampleStep(s,1,new[]{"target"},new[]{"target"},new[]{"target"}).Length==0,"substeps must be spatially ordered");Float3 a,b,c,d;s.ReadStep(0,out a,out b,out c,out d);Check(R24KnifeMath.Length(R24KnifeMath.Sub(d,c))>.2209f,"interpolated actual blade chord retained");var hull=R24KnifeMath.HullPoints(a,b,c,d);Check(hull.Length==24,"source continuous quadrilateral hull includes six-axis blade thickness");var rotate=R24KnifeMath.HullPoints(new Float3(),new Float3(0,.221f,0),new Float3(),new Float3(.221f,0,0));Check(rotate.Length==204,"source intermediate orientations at .10rad cover rotating blade arc");Check(Math.Abs(R24KnifeMath.Length(R24KnifeMath.Sub(hull[0],a))-.026f)<.000001f,"exact source blade contact radius");other.Retire();Check(Frame(other,2.3f)==null&&!other.ApplyContact(entries[0],hit),"native lifetime retirement blocks all future contacts");Console.WriteLine("PASS "+checks+" staged native bound knife contact/real Health/motion/geometry cases");}
 static void Main(){new Cases().Run();}
}
